source='''def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    # The pair defining the main line is the farthest aligned pair.
    candidates = []
    for i, (r1, c1) in enumerate(points):
        for r2, c2 in points[i + 1:]:
            if r1 == r2:
                candidates.append((c2 - c1, "h", r1, min(c1, c2), max(c1, c2)))
            elif c1 == c2:
                candidates.append((r2 - r1, "v", c1, min(r1, r2), max(r1, r2)))
    _, axis, fixed, lo, hi = max(candidates)
    if axis == "h":
        for c in range(lo, hi + 1):
            if out[fixed][c] == 0:
                out[fixed][c] = 3
        for r, c in points:
            if r != fixed and lo <= c <= hi:
                for rr in range(min(r, fixed), max(r, fixed) + 1):
                    if out[rr][c] == 0:
                        out[rr][c] = 3
    else:
        for r in range(lo, hi + 1):
            if out[r][fixed] == 0:
                out[r][fixed] = 3
        for r, c in points:
            if c != fixed and lo <= r <= hi:
                for cc in range(min(c, fixed), max(c, fixed) + 1):
                    if out[r][cc] == 0:
                        out[r][cc] = 3
    return out
'''
